=== FILE: axil_timer.v ===
// axil_timer: 32-bit down-counting timer, one-shot and periodic modes, level
// interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md following microarchitecture.md.
`default_nettype none

module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  localparam [1:0] IDX_CTRL   = 2'd0;
  localparam [1:0] IDX_LOAD   = 2'd1;
  localparam [1:0] IDX_COUNT  = 2'd2;
  localparam [1:0] IDX_STATUS = 2'd3;

  // ---------------------------------------------------------------- state
  reg                  aw_held;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg                  w_held;
  reg [31:0]           w_data_q;
  reg [3:0]            w_strb_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [31:0]           rdata_q;
  reg [1:0]            rresp_q;

  reg                  en_q;
  reg                  ie_q;
  reg                  mode_q;
  reg                  expired_q;
  reg [31:0]           load_q;
  reg [31:0]           count_q;

  // ---------------------------------------------------------------- write channel
  assign s_axil_awready = ~aw_held & ~bvalid_q;
  assign s_axil_wready  = ~w_held & ~bvalid_q;

  wire aw_hs    = s_axil_awvalid & s_axil_awready;
  wire w_hs     = s_axil_wvalid & s_axil_wready;
  wire have_aw  = aw_held | aw_hs;
  wire have_w   = w_held | w_hs;
  wire do_write = have_aw & have_w;

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
  wire [31:0]           wr_data = w_held ? w_data_q : s_axil_wdata;
  wire [3:0]            wr_strb = w_held ? w_strb_q : s_axil_wstrb;

  wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                         ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] wr_idx    = wr_addr[3:2];

  wire wr_ok    = wr_mapped & (wr_idx != IDX_COUNT);
  wire ctrl_wr  = do_write & wr_mapped & (wr_idx == IDX_CTRL) & wr_strb[0];
  wire load_wr  = do_write & wr_mapped & (wr_idx == IDX_LOAD);
  wire stat_clr = do_write & wr_mapped & (wr_idx == IDX_STATUS) &
                  wr_strb[0] & wr_data[0];

  wire [31:0] load_merged = {
    (wr_strb[3] ? wr_data[31:24] : load_q[31:24]),
    (wr_strb[2] ? wr_data[23:16] : load_q[23:16]),
    (wr_strb[1] ? wr_data[15:8]  : load_q[15:8]),
    (wr_strb[0] ? wr_data[7:0]   : load_q[7:0])
  };

  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held   <= 1'b0;
      aw_addr_q <= {ADDR_WIDTH{1'b0}};
      w_held    <= 1'b0;
      w_data_q  <= 32'd0;
      w_strb_q  <= 4'd0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
    end else begin
      if (aw_hs) begin
        aw_addr_q <= s_axil_awaddr;
        aw_held   <= 1'b1;
      end
      if (w_hs) begin
        w_data_q <= s_axil_wdata;
        w_strb_q <= s_axil_wstrb;
        w_held   <= 1'b1;
      end
      if (bvalid_q && s_axil_bready) begin
        bvalid_q <= 1'b0;
      end
      if (do_write) begin
        aw_held  <= 1'b0;
        w_held   <= 1'b0;
        bvalid_q <= 1'b1;
        bresp_q  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
      end
    end
  end

  assign s_axil_bvalid = bvalid_q;
  assign s_axil_bresp  = bresp_q;

  // ---------------------------------------------------------------- read channel
  assign s_axil_arready = ~rvalid_q;

  wire       ar_hs     = s_axil_arvalid & s_axil_arready;
  wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                         ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] rd_idx    = s_axil_araddr[3:2];
  wire [1:0] rd_resp   = rd_mapped ? RESP_OKAY : RESP_SLVERR;

  reg [31:0] rd_data;

  always @* begin
    rd_data = 32'd0;
    case (rd_idx)
      IDX_CTRL:   rd_data = {29'd0, mode_q, ie_q, en_q};
      IDX_LOAD:   rd_data = load_q;
      IDX_COUNT:  rd_data = count_q;
      IDX_STATUS: rd_data = {31'd0, expired_q};
      default:    rd_data = 32'd0;
    endcase
    if (!rd_mapped) begin
      rd_data = 32'd0;
    end
  end

  always @(posedge aclk) begin
    if (!aresetn) begin
      rvalid_q <= 1'b0;
      rdata_q  <= 32'd0;
      rresp_q  <= RESP_OKAY;
    end else begin
      if (ar_hs) begin
        rvalid_q <= 1'b1;
        rdata_q  <= rd_data;
        rresp_q  <= rd_resp;
      end else if (s_axil_rready) begin
        rvalid_q <= 1'b0;
      end
    end
  end

  assign s_axil_rvalid = rvalid_q;
  assign s_axil_rdata  = rdata_q;
  assign s_axil_rresp  = rresp_q;

  // ---------------------------------------------------------------- timer
  // count_end: the last cycle of a count. A count of 0 is treated like 1.
  wire count_end = en_q & (count_q <= 32'd1);

  // Order inside the block gives the spec priorities (last assignment wins):
  // 1 count step, 2 expired clear then set, 3 CTRL write, 4 LOAD write.
  always @(posedge aclk) begin
    if (!aresetn) begin
      en_q      <= 1'b0;
      ie_q      <= 1'b0;
      mode_q    <= 1'b0;
      expired_q <= 1'b0;
      load_q    <= 32'd0;
      count_q   <= 32'd0;
    end else begin
      // 1. count step
      if (en_q) begin
        if (count_end) begin
          if (mode_q) begin
            count_q <= load_q;
          end else begin
            count_q <= 32'd0;
            en_q    <= 1'b0;
          end
        end else begin
          count_q <= count_q - 32'd1;
        end
      end
      // 2. expired: clear, then set (a count end beats a clear)
      if (stat_clr) begin
        expired_q <= 1'b0;
      end
      if (count_end) begin
        expired_q <= 1'b1;
      end
      // 3. CTRL write wins for en and count
      if (ctrl_wr) begin
        ie_q   <= wr_data[1];
        mode_q <= wr_data[2];
        if (wr_data[0]) begin
          en_q    <= 1'b1;
          count_q <= load_q;
        end else begin
          en_q <= 1'b0;
        end
      end
      // 4. LOAD write, byte merge
      if (load_wr) begin
        load_q <= load_merged;
      end
    end
  end

  assign irq = expired_q & ie_q;

endmodule

`default_nettype wire
=== END FILE ===
