// Self-checking testbench for axil_timer. Two lanes, ADDR_WIDTH 4 and 8.
`default_nettype none

module axil_timer_tb;
  reg            clk;
  wire [31:0]    passed4;
  wire [31:0]    failed4;
  wire [31:0]    passed8;
  wire [31:0]    failed8;
  wire           done4;
  wire           done8;
  reg [8*64-1:0] nonce;
  integer        rc;

  initial clk = 1'b0;
  always #5 clk = ~clk;

  axil_timer_tb_lane #(.AW(4)) lane4 (.clk(clk), .passed(passed4), .failed(failed4), .done(done4));
  axil_timer_tb_lane #(.AW(8)) lane8 (.clk(clk), .passed(passed8), .failed(failed8), .done(done8));

  initial begin
    nonce = {64{8'h00}};
    rc = $value$plusargs("nirmaan_nonce=%s", nonce);
    if (rc == 0) nonce = {64{8'h00}};
    wait ((done4 === 1'b1) && (done8 === 1'b1));
    @(negedge clk);
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed4 + passed8, failed4 + failed8);
    $finish;
  end

  initial begin
    #2000000;
    $error("axil_timer_tb: timeout before both lanes finished");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed4 + passed8,
             failed4 + failed8 + 32'd1);
    $finish;
  end
endmodule

module axil_timer_tb_lane #(
    parameter integer AW = 4
) (
    input  wire        clk,
    output reg  [31:0] passed,
    output reg  [31:0] failed,
    output reg         done
);
  localparam [1:0] OKAY   = 2'b00;
  localparam [1:0] SLVERR = 2'b10;

  reg          aresetn;
  reg [AW-1:0] awaddr;
  reg          awvalid;
  wire         awready;
  reg [31:0]   wdata;
  reg [3:0]    wstrb;
  reg          wvalid;
  wire         wready;
  wire [1:0]   bresp;
  wire         bvalid;
  reg          bready;
  reg [AW-1:0] araddr;
  reg          arvalid;
  wire         arready;
  wire [31:0]  rdata;
  wire [1:0]   rresp;
  wire         rvalid;
  reg          rready;
  wire         irq;

  axil_timer #(.ADDR_WIDTH(AW)) dut (
    .aclk(clk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready),
    .s_axil_bresp(bresp), .s_axil_bvalid(bvalid), .s_axil_bready(bready),
    .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready),
    .s_axil_rdata(rdata), .s_axil_rresp(rresp), .s_axil_rvalid(rvalid), .s_axil_rready(rready),
    .irq(irq)
  );

  // Edge counter: at the negedge after rising edge k, edge_cnt == k.
  integer edge_cnt;
  reg     irq_last;
  integer irq_rises;
  integer irq_rise_edge;   // edge after which irq was first seen high

  initial begin
    edge_cnt      = 0;
    irq_last      = 1'b0;
    irq_rises     = 0;
    irq_rise_edge = -1;
  end

  always @(posedge clk) begin
    edge_cnt <= edge_cnt + 1;
    irq_last <= irq;
    if (irq && !irq_last) begin
      irq_rises     <= irq_rises + 1;
      irq_rise_edge <= edge_cnt;
    end
  end

  integer    last_wr_edge;
  integer    last_ar_edge;
  reg [31:0] load_m;
  reg [1:0]  wresp;
  reg [31:0] rdat;
  reg [1:0]  rrsp;

  // ------------------------------------------------------------ checks
  task fail(input integer id);
    begin
      failed = failed + 32'd1;
      $error("axil_timer_tb lane AW=%0d: check %0d failed at edge %0d", AW, id, edge_cnt);
    end
  endtask

  task check_true(input c, input integer id);
    begin
      if (c === 1'b1) passed = passed + 32'd1;
      else fail(id);
    end
  endtask

  task check_eq(input [31:0] got, input [31:0] exp, input integer id);
    begin
      if (got === exp) begin
        passed = passed + 32'd1;
      end else begin
        failed = failed + 32'd1;
        $error("axil_timer_tb lane AW=%0d: check %0d got 0x%08h expected 0x%08h", AW, id, got, exp);
      end
    end
  endtask

  function [31:0] merge;
    input [31:0] old_v;
    input [31:0] new_v;
    input [3:0]  strb;
    integer k;
    begin
      merge = old_v;
      for (k = 0; k < 4; k = k + 1)
        if (strb[k]) merge[8*k +: 8] = new_v[8*k +: 8];
    end
  endfunction

  // ------------------------------------------------------------ bus tasks
  // All tasks start and end at a negedge with every VALID low.
  task automatic axi_write(input [7:0] a, input [31:0] d, input [3:0] s,
                           input integer aw_dly, input integer w_dly, input integer b_dly,
                           output [1:0] resp);
    integer   cyc;
    reg       aw_done;
    reg       w_done;
    reg       b_done;
    reg       hs_aw;
    reg       hs_w;
    reg       hs_b;
    reg       stall;
    reg [1:0] bresp_hold;
    begin
      cyc = 0; aw_done = 1'b0; w_done = 1'b0; b_done = 1'b0; stall = 1'b0;
      bresp_hold = 2'b00; resp = 2'b11;
      awaddr = a[AW-1:0]; wdata = d; wstrb = s;
      while (!b_done) begin
        awvalid = !aw_done && (cyc >= aw_dly);
        wvalid  = !w_done && (cyc >= w_dly);
        bready  = (cyc >= b_dly);
        if (!(aw_done && w_done) && bvalid) fail(100);
        if (aw_done && !w_done && awready) fail(104);
        if (w_done && !aw_done && wready) fail(105);
        if (stall && (bresp !== bresp_hold)) fail(101);
        if (bvalid && !bready) begin
          stall = 1'b1;
          bresp_hold = bresp;
          if (awready || wready) fail(102);
        end
        hs_aw = awvalid && awready;
        hs_w  = wvalid && wready;
        hs_b  = bvalid && bready;
        if (hs_b) resp = bresp;
        @(posedge clk);
        if (hs_aw) aw_done = 1'b1;
        if (hs_w) w_done = 1'b1;
        if (hs_b) b_done = 1'b1;
        @(negedge clk);
        if ((hs_aw || hs_w) && aw_done && w_done) last_wr_edge = edge_cnt;
        cyc = cyc + 1;
        if (cyc > 1000) begin
          fail(103);
          b_done = 1'b1;
        end
      end
      awvalid = 1'b0; wvalid = 1'b0; bready = 1'b0;
    end
  endtask

  task automatic axi_read(input [7:0] a, input integer r_dly,
                          output [31:0] data, output [1:0] resp);
    integer    cyc;
    reg        ar_done;
    reg        r_done;
    reg        hs_ar;
    reg        hs_r;
    reg        stall;
    reg [31:0] dh;
    reg [1:0]  rh;
    begin
      cyc = 0; ar_done = 1'b0; r_done = 1'b0; stall = 1'b0;
      dh = 32'd0; rh = 2'b00; data = 32'd0; resp = 2'b11;
      araddr = a[AW-1:0];
      while (!r_done) begin
        arvalid = !ar_done;
        rready  = ar_done && (cyc >= r_dly);
        if (!ar_done && rvalid) fail(110);
        if (stall && ((rdata !== dh) || (rresp !== rh))) fail(111);
        if (rvalid && !rready) begin
          stall = 1'b1;
          dh = rdata;
          rh = rresp;
          if (arready) fail(112);
        end
        hs_ar = arvalid && arready;
        hs_r  = rvalid && rready;
        if (hs_r) begin
          data = rdata;
          resp = rresp;
        end
        @(posedge clk);
        if (hs_ar) ar_done = 1'b1;
        if (hs_r) r_done = 1'b1;
        @(negedge clk);
        if (hs_ar) last_ar_edge = edge_cnt;
        cyc = cyc + 1;
        if (cyc > 1000) begin
          fail(113);
          r_done = 1'b1;
        end
      end
      arvalid = 1'b0; rready = 1'b0;
    end
  endtask

  task automatic wr_check(input [7:0] a, input [31:0] d, input [3:0] s,
                          input [1:0] exp_resp, input integer id);
    begin
      axi_write(a, d, s, 0, 0, 0, wresp);
      check_eq({30'd0, wresp}, {30'd0, exp_resp}, id);
    end
  endtask

  task automatic rd_check(input [7:0] a, input [31:0] exp, input [1:0] exp_resp,
                          input integer id);
    begin
      axi_read(a, 0, rdat, rrsp);
      check_eq(rdat, exp, id);
      check_eq({30'd0, rrsp}, {30'd0, exp_resp}, id);
    end
  endtask

  task automatic idle(input integer n);
    begin
      repeat (n) @(negedge clk);
    end
  endtask

  task automatic wait_rises(input integer target, input integer maxc, input integer id);
    integer i;
    begin
      i = 0;
      while ((irq_rises < target) && (i < maxc)) begin
        @(negedge clk);
        i = i + 1;
      end
      if (irq_rises < target) fail(id);
      else passed = passed + 32'd1;
    end
  endtask

  task automatic wait_until_edge(input integer target, input integer id);
    begin
      if (edge_cnt > target) fail(id);
      while (edge_cnt < target) @(negedge clk);
    end
  endtask

  // One-shot count of n, timed to the edge.
  task automatic oneshot(input integer n, input integer id);
    integer len;
    integer t0;
    integer b0;
    begin
      len = (n == 0) ? 1 : n;
      wr_check(8'h00, 32'h0, 4'hF, OKAY, id);
      wr_check(8'h04, n, 4'hF, OKAY, id + 1);
      wr_check(8'h0C, 32'h1, 4'hF, OKAY, id + 2);
      check_true(!irq, id + 3);
      b0 = irq_rises;
      wr_check(8'h00, 32'h3, 4'hF, OKAY, id + 4);
      t0 = last_wr_edge;
      wait_rises(b0 + 1, len + 20, id + 5);
      check_eq(irq_rise_edge, t0 + len, id + 6);
      rd_check(8'h00, 32'h2, OKAY, id + 7);
      rd_check(8'h08, 32'h0, OKAY, id + 8);
      rd_check(8'h0C, 32'h1, OKAY, id + 9);
      check_true(irq, id + 10);
      wr_check(8'h0C, 32'h1, 4'hF, OKAY, id + 11);
      check_true(!irq, id + 12);
      idle(2 * len + 20);
      check_eq(irq_rises, b0 + 1, id + 13);
      check_true(!irq, id + 14);
    end
  endtask

  // ------------------------------------------------------------ sequence
  integer    t_e;
  integer    t_r;
  integer    t_s;
  integer    t_a;
  integer    t_w;
  integer    base;
  integer    n_per;
  integer    expc;
  integer    p;
  reg [7:0]  a8;

  initial begin
    passed = 32'd0; failed = 32'd0; done = 1'b0;
    aresetn = 1'b0;
    awaddr = {AW{1'b0}}; awvalid = 1'b0; wdata = 32'd0; wstrb = 4'd0; wvalid = 1'b0;
    bready = 1'b0; araddr = {AW{1'b0}}; arvalid = 1'b0; rready = 1'b0;
    last_wr_edge = 0; last_ar_edge = 0; load_m = 32'd0;
    wresp = 2'b00; rdat = 32'd0; rrsp = 2'b00; a8 = 8'h00;
    t_e = 0; t_r = 0; t_s = 0; t_a = 0; t_w = 0; base = 0; n_per = 0; expc = 0; p = 0;
    repeat (5) @(negedge clk);
    aresetn = 1'b1;
    @(negedge clk);

    // ---- reset values
    check_true(awready, 1);
    check_true(wready, 2);
    check_true(arready, 3);
    check_true(!bvalid, 4);
    check_true(!rvalid, 5);
    check_true(!irq, 6);
    rd_check(8'h00, 32'h0, OKAY, 10);
    rd_check(8'h04, 32'h0, OKAY, 11);
    rd_check(8'h08, 32'h0, OKAY, 12);
    rd_check(8'h0C, 32'h0, OKAY, 13);

    // ---- LOAD with partial strobes
    load_m = 32'd0;
    wr_check(8'h04, 32'h11223344, 4'hF, OKAY, 20);
    load_m = merge(load_m, 32'h11223344, 4'hF);
    rd_check(8'h04, load_m, OKAY, 21);
    wr_check(8'h04, 32'hAABBCCDD, 4'b0101, OKAY, 22);
    load_m = merge(load_m, 32'hAABBCCDD, 4'b0101);
    rd_check(8'h04, load_m, OKAY, 23);
    wr_check(8'h04, 32'h55667788, 4'b1010, OKAY, 24);
    load_m = merge(load_m, 32'h55667788, 4'b1010);
    rd_check(8'h04, load_m, OKAY, 25);
    wr_check(8'h04, 32'hFFFFFFFF, 4'b0000, OKAY, 26);
    load_m = merge(load_m, 32'hFFFFFFFF, 4'b0000);
    rd_check(8'h04, load_m, OKAY, 27);
    wr_check(8'h04, 32'h000000EE, 4'b0001, OKAY, 28);
    load_m = merge(load_m, 32'h000000EE, 4'b0001);
    rd_check(8'h04, load_m, OKAY, 29);
    wr_check(8'h04, 32'h99000000, 4'b1000, OKAY, 30);
    load_m = merge(load_m, 32'h99000000, 4'b1000);
    rd_check(8'h04, load_m, OKAY, 31);

    // ---- channel orders and backpressure
    axi_write(8'h04, 32'hCAFEF00D, 4'hF, 0, 3, 0, wresp);   // AW before W
    check_eq({30'd0, wresp}, 32'd0, 40);
    load_m = 32'hCAFEF00D;
    rd_check(8'h04, load_m, OKAY, 41);
    axi_write(8'h04, 32'h0BADBEEF, 4'hF, 4, 0, 0, wresp);   // W before AW
    check_eq({30'd0, wresp}, 32'd0, 42);
    load_m = 32'h0BADBEEF;
    rd_check(8'h04, load_m, OKAY, 43);
    axi_write(8'h04, 32'h12345678, 4'hF, 0, 0, 6, wresp);   // together, B stalled
    check_eq({30'd0, wresp}, 32'd0, 44);
    load_m = 32'h12345678;
    axi_write(8'h04, 32'h87654321, 4'hF, 2, 5, 9, wresp);   // mixed
    check_eq({30'd0, wresp}, 32'd0, 45);
    load_m = 32'h87654321;
    axi_read(8'h04, 5, rdat, rrsp);                         // R stalled
    check_eq(rdat, load_m, 46);
    check_eq({30'd0, rrsp}, 32'd0, 47);
    axi_write(8'h08, 32'h1, 4'hF, 0, 0, 4, wresp);          // SLVERR held under stall
    check_eq({30'd0, wresp}, {30'd0, SLVERR}, 48);
    axi_read(8'h06, 3, rdat, rrsp);                         // SLVERR held under stall
    check_eq(rdat, 32'd0, 49);
    check_eq({30'd0, rrsp}, {30'd0, SLVERR}, 50);

    // ---- COUNT read only, unmapped policy
    wr_check(8'h08, 32'h00001234, 4'hF, SLVERR, 60);
    rd_check(8'h08, 32'h0, OKAY, 61);
    wr_check(8'h05, 32'hFFFFFFFF, 4'hF, SLVERR, 62);
    rd_check(8'h04, load_m, OKAY, 63);
    wr_check(8'h01, 32'h00000007, 4'hF, SLVERR, 64);
    rd_check(8'h00, 32'h0, OKAY, 65);
    rd_check(8'h06, 32'h0, SLVERR, 66);
    rd_check(8'h0B, 32'h0, SLVERR, 67);
    if (AW > 4) begin
      wr_check(8'h14, 32'hDEADDEAD, 4'hF, SLVERR, 70);
      rd_check(8'h04, load_m, OKAY, 71);
      wr_check(8'h10, 32'h00000007, 4'hF, SLVERR, 72);
      rd_check(8'h00, 32'h0, OKAY, 73);
      wr_check(8'h1C, 32'h00000001, 4'hF, SLVERR, 74);
      wr_check(8'hFC, 32'h00000001, 4'hF, SLVERR, 75);
      rd_check(8'h0C, 32'h0, OKAY, 76);
      rd_check(8'h10, 32'h0, SLVERR, 77);
      rd_check(8'h14, 32'h0, SLVERR, 78);
      rd_check(8'h18, 32'h0, SLVERR, 79);
      rd_check(8'h1C, 32'h0, SLVERR, 80);
      rd_check(8'hFC, 32'h0, SLVERR, 81);
      idle(5);
      check_true(!irq, 82);
    end

    // ---- CTRL write without wstrb[0]
    wr_check(8'h04, 32'h00000003, 4'hF, OKAY, 90);
    load_m = 32'h3;
    wr_check(8'h00, 32'h00000007, 4'b1110, OKAY, 91);
    rd_check(8'h00, 32'h0, OKAY, 92);
    idle(10);
    rd_check(8'h08, 32'h0, OKAY, 93);
    rd_check(8'h0C, 32'h0, OKAY, 94);
    check_true(!irq, 95);

    // ---- one-shot counts timed to the cycle
    oneshot(5, 200);
    oneshot(1, 220);
    oneshot(0, 240);
    oneshot(37, 260);

    // ---- COUNT read mid-count (value on the edge the address is accepted)
    wr_check(8'h00, 32'h0, 4'hF, OKAY, 300);
    wr_check(8'h04, 32'd40, 4'hF, OKAY, 301);
    wr_check(8'h0C, 32'h1, 4'hF, OKAY, 302);
    base = irq_rises;
    wr_check(8'h00, 32'h3, 4'hF, OKAY, 303);
    t_e = last_wr_edge;
    idle(5);
    axi_read(8'h08, 4, rdat, rrsp);
    t_a = last_ar_edge;
    check_eq(rdat, 40 - (t_a - 1 - t_e), 304);
    check_eq({30'd0, rrsp}, 32'd0, 305);
    axi_read(8'h08, 0, rdat, rrsp);
    t_a = last_ar_edge;
    check_eq(rdat, 40 - (t_a - 1 - t_e), 306);
    wait_rises(base + 1, 60, 307);
    check_eq(irq_rise_edge, t_e + 40, 308);
    rd_check(8'h08, 32'h0, OKAY, 309);

    // ---- interrupt enable on a pending expiry; STATUS write rules
    wr_check(8'h00, 32'h0, 4'hF, OKAY, 320);
    wr_check(8'h04, 32'd4, 4'hF, OKAY, 321);
    wr_check(8'h0C, 32'h1, 4'hF, OKAY, 322);
    wr_check(8'h00, 32'h1, 4'hF, OKAY, 323);
    idle(12);
    check_true(!irq, 324);
    rd_check(8'h0C, 32'h1, OKAY, 325);
    rd_check(8'h00, 32'h0, OKAY, 326);
    base = irq_rises;
    wr_check(8'h00, 32'h2, 4'hF, OKAY, 327);
    t_w = last_wr_edge;
    check_true(irq, 328);
    idle(2);
    check_eq(irq_rises, base + 1, 329);
    check_eq(irq_rise_edge, t_w, 330);
    wr_check(8'h00, 32'h0, 4'hF, OKAY, 331);
    check_true(!irq, 332);
    rd_check(8'h0C, 32'h1, OKAY, 333);
    wr_check(8'h0C, 32'h1, 4'b1110, OKAY, 334);
    rd_check(8'h0C, 32'h1, OKAY, 335);
    wr_check(8'h0C, 32'h0, 4'hF, OKAY, 336);
    rd_check(8'h0C, 32'h1, OKAY, 337);
    wr_check(8'h0C, 32'h1, 4'h1, OKAY, 338);
    rd_check(8'h0C, 32'h0, OKAY, 339);

    // ---- CTRL restart landing on the edge a count ends
    wr_check(8'h00, 32'h0, 4'hF, OKAY, 400);
    wr_check(8'h04, 32'd12, 4'hF, OKAY, 401);
    wr_check(8'h0C, 32'h1, 4'hF, OKAY, 402);
    base = irq_rises;
    wr_check(8'h00, 32'h3, 4'hF, OKAY, 403);
    t_e = last_wr_edge;
    wait_until_edge(t_e + 11, 404);
    axi_write(8'h00, 32'h3, 4'hF, 0, 0, 0, wresp);
    check_eq(last_wr_edge, t_e + 12, 405);
    idle(2);
    check_eq(irq_rises, base + 1, 406);
    check_eq(irq_rise_edge, t_e + 12, 407);
    rd_check(8'h00, 32'h3, OKAY, 408);
    wr_check(8'h0C, 32'h1, 4'hF, OKAY, 409);
    check_true(!irq, 410);
    wait_rises(base + 2, 40, 411);
    check_eq(irq_rise_edge, t_e + 24, 412);

    // ---- restart while running
    wr_check(8'h00, 32'h0, 4'hF, OKAY, 420);
    wr_check(8'h04, 32'd30, 4'hF, OKAY, 421);
    wr_check(8'h0C, 32'h1, 4'hF, OKAY, 422);
    base = irq_rises;
    wr_check(8'h00, 32'h3, 4'hF, OKAY, 423);
    t_e = last_wr_edge;
    idle(10);
    wr_check(8'h00, 32'h3, 4'hF, OKAY, 424);
    t_r = last_wr_edge;
    wait_rises(base + 1, 80, 425);
    check_eq(irq_rise_edge, t_r + 30, 426);
    wr_check(8'h0C, 32'h1, 4'hF, OKAY, 427);
    idle(40);
    check_eq(irq_rises, base + 1, 428);

    // ---- periodic over several periods
    n_per = 16;
    wr_check(8'h00, 32'h0, 4'hF, OKAY, 600);
    wr_check(8'h04, n_per, 4'hF, OKAY, 601);
    wr_check(8'h0C, 32'h1, 4'hF, OKAY, 602);
    base = irq_rises;
    wr_check(8'h00, 32'h7, 4'hF, OKAY, 603);
    t_e = last_wr_edge;
    for (p = 1; p <= 3; p = p + 1) begin
      wait_rises(base + p, n_per + 20, 610 + p);
      check_eq(irq_rise_edge, t_e + p * n_per, 620 + p);
      rd_check(8'h00, 32'h7, OKAY, 630 + p);
      wr_check(8'h0C, 32'h1, 4'hF, OKAY, 640 + p);
      check_true(!irq, 650 + p);
    end
    // acknowledge on the very edge the 4th count ends: the expiry is kept
    wait_until_edge(t_e + 4 * n_per - 1, 660);
    check_true(!irq, 661);
    axi_write(8'h0C, 32'h1, 4'hF, 0, 0, 0, wresp);
    check_eq(last_wr_edge, t_e + 4 * n_per, 662);
    check_true(irq, 663);
    idle(2);
    check_eq(irq_rises, base + 4, 664);
    check_eq(irq_rise_edge, t_e + 4 * n_per, 665);
    rd_check(8'h0C, 32'h1, OKAY, 666);
    wr_check(8'h0C, 32'h1, 4'hF, OKAY, 667);
    check_true(!irq, 668);
    wait_rises(base + 5, n_per + 20, 669);
    check_eq(irq_rise_edge, t_e + 5 * n_per, 670);
    wr_check(8'h0C, 32'h1, 4'hF, OKAY, 671);
    check_true(!irq, 672);

    // ---- stop freezes COUNT; COUNT write SLVERR with a non-zero count
    wr_check(8'h00, 32'h6, 4'hF, OKAY, 680);
    t_s = last_wr_edge;
    expc = n_per - ((t_s - t_e) % n_per);
    rd_check(8'h00, 32'h6, OKAY, 681);
    rd_check(8'h08, expc, OKAY, 682);
    idle(3 * n_per);
    rd_check(8'h08, expc, OKAY, 683);
    check_eq(irq_rises, base + 5, 684);
    check_true(!irq, 685);
    wr_check(8'h08, 32'h0, 4'hF, SLVERR, 686);
    rd_check(8'h08, expc, OKAY, 687);

    // ---- restart from LOAD (one-shot)
    base = irq_rises;
    wr_check(8'h00, 32'h3, 4'hF, OKAY, 690);
    t_r = last_wr_edge;
    wait_rises(base + 1, n_per + 20, 691);
    check_eq(irq_rise_edge, t_r + n_per, 692);
    rd_check(8'h00, 32'h2, OKAY, 693);

    // ---- reset during a count, with a held write address
    wr_check(8'h00, 32'h0, 4'hF, OKAY, 700);
    wr_check(8'h04, 32'd50, 4'hF, OKAY, 701);
    wr_check(8'h0C, 32'h1, 4'hF, OKAY, 702);
    wr_check(8'h00, 32'h7, 4'hF, OKAY, 703);
    idle(10);
    a8 = 8'h04;
    awaddr = a8[AW-1:0];
    check_true(awready, 704);
    awvalid = 1'b1;
    @(negedge clk);
    awvalid = 1'b0;
    check_true(!awready, 705);
    aresetn = 1'b0;
    idle(3);
    aresetn = 1'b1;
    check_true(awready, 706);
    check_true(wready, 707);
    check_true(arready, 708);
    check_true(!bvalid, 709);
    check_true(!rvalid, 710);
    check_true(!irq, 711);
    rd_check(8'h00, 32'h0, OKAY, 712);
    rd_check(8'h04, 32'h0, OKAY, 713);
    rd_check(8'h08, 32'h0, OKAY, 714);
    rd_check(8'h0C, 32'h0, OKAY, 715);
    base = irq_rises;
    idle(80);
    check_eq(irq_rises, base, 716);
    wr_check(8'h04, 32'd5, 4'hF, OKAY, 717);
    rd_check(8'h04, 32'd5, OKAY, 718);

    done = 1'b1;
  end
endmodule

`default_nettype wire
